def separate_paren_groups(paren_string: str) -> List[str]:
    """
    Separate groups of nested parentheses from a given string.
    """
    stack = []
    groups = []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if len(stack) == 0:
                raise ValueError('Unexpected close brace')
            stack.pop()
        else:
            continue

    if len(stack) != 0:
        raise ValueError('Unbalanced parentheses')

    balanced_string = ''.join(stack)
    balanced_string = balanced_string.replace('(', ', ')
    balanced_string = balanced_string.replace(')', '')
    groups = balanced_string.split(', ')
    return groups

