  # Calculate the maximum sum of values collected on two paths in an N x N grid
  # This function utilizes dynamic programming to find two paths from the top-left corner to the bottom-right corner of the grid which maximize the sum of the values collected
  # Each value can be collected at most once, even if both paths pass through it

  # Initialize the grid with zero values
  grid = [[0 for _ in range(N)] for _ in range(N)]

  # Populate the grid with the input values
  for x, y, value in grid_values:
    grid[x][y] = value

  # Initialize the two paths
  path1 = [0] * N
  path2 = [0] * N

  # Fill in the two paths and calculate the maximum sum of values collected
  for i in range(N):
    for j in range(N):
      if i == 0 and j == 0:
        continue
      elif i == 0:
        path1[j] = grid[0][j]
        path2[j] = 0
      elif j == 0:
        path1[i] = 0
        path2[i] = grid[i][0]
      else:
        path1[i] = max(path1[i-1], path2[i-1]) + grid[i][j]
        path2[i] = max(path2[i-1], path1[i-1]) + grid[i][j]

  # Return the maximum sum of values collected
  return max(path1[-1], path2[-1])

