def cantor_numbering(N: int) -> str:

    # Step 1: Handle invalid inputs
    if N < 1:
        raise ValueError("N must be a positive integer.")

    # Step 2: Initialize the numerator and denominator
    n = 1
    d = 1
    c = 1

    # Step 3: Loop until the N-th term is found
    while c < N:
        n += d
        d += 1

        if n == N:
            break
        else:
            c += 1

    # Step 4: Return the fraction as a string
    return str(n) + "/" + str(d)

