    chatting_pairs = set(chatting_pairs)

    # Function to count the number of chatting pairs that can be separated by adding an aisle in a given position
    def count_chatting_pairs(position):
        count = 0
        for pair in chatting_pairs:
            if pair[0] == position[0] or pair[1] == position[1]:
                count += 1
        return count

    # Function to calculate the cost of adding a horizontal aisle
    def calculate_horizontal_cost(position):
        count = count_chatting_pairs(position)
        return count * (K + D)

    # Function to calculate the cost of adding a vertical aisle
